package io.github.finalparadox.entity;
import io.github.finalparadox.registry.ModEntities;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.ClientGamePacketListener;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraftforge.network.NetworkHooks;import java.util.UUID;
public final class PumpkinBarrageEntity extends Entity{private UUID ownerId;public PumpkinBarrageEntity(EntityType<PumpkinBarrageEntity>t,Level l){super(t,l);noPhysics=true;}public static void spawn(ServerPlayer owner){for(PumpkinBarrageEntity e:owner.serverLevel().getEntitiesOfClass(PumpkinBarrageEntity.class,owner.getBoundingBox().inflate(128),x->owner.getUUID().equals(x.ownerId)))e.discard();PumpkinBarrageEntity e=new PumpkinBarrageEntity(ModEntities.PUMPKIN_BARRAGE.get(),owner.serverLevel());e.ownerId=owner.getUUID();e.setPos(owner.position());owner.serverLevel().addFreshEntity(e);}@Override protected void defineSynchedData(){}@Override public void tick(){super.tick();if(level().isClientSide)return;ServerPlayer owner=ownerId==null||!(level() instanceof ServerLevel s)?null:s.getServer().getPlayerList().getPlayer(ownerId);if(owner==null||tickCount>15){discard();return;}setPos(owner.position());PumpkinBombEntity.spawn(owner,position(),.4);PumpkinBombEntity.spawn(owner,position(),.4);}@Override protected void readAdditionalSaveData(CompoundTag t){if(t.hasUUID("Owner"))ownerId=t.getUUID("Owner");}@Override protected void addAdditionalSaveData(CompoundTag t){if(ownerId!=null)t.putUUID("Owner",ownerId);}@Override public Packet<ClientGamePacketListener>getAddEntityPacket(){return NetworkHooks.getEntitySpawningPacket(this);}}
